# The search found no cube numbers up to 500^3
# Let me expand the search significantly

def find_cube_taxicab(limit=2000):
    """Find cube numbers that are sums of two cubes in two different ways"""
    sums = {}

    for a in range(1, limit):
        a3 = a ** 3
        for b in range(a + 1, limit):
            s = a3 + b ** 3
            if s not in sums:
                sums[s] = []
            sums[s].append((a, b))

    results = []
    for s, pairs in sums.items():
        if len(pairs) >= 2:
            # Check if s is a perfect cube
            cube_root = round(s ** (1/3))
            if abs(cube_root ** 3 - s) < 0.0001 or cube_root ** 3 == s:
                # Verify it's really a perfect cube
                cr = int(round(s ** (1/3)))
                if cr ** 3 == s:
                    results.append((s, cr, pairs))

    results.sort()
    return results

print("Searching up to 2000...")
cube_results = find_cube_taxicab(2000)

if cube_results:
    print("Found cube numbers that are sums of two different positive cubes in two different ways:")
    for s, cube_root, pairs in cube_results[:10]:
        print(f"{s} = {cube_root}^3 = ", end="")
        representations = []
        for a, b in pairs:
            representations.append(f"{a}^3 + {b}^3")
        print(" = ".join(representations))
else:
    print("None found up to 2000")

# Let's try an even larger search
print("\nSearching up to 5000...")
cube_results = find_cube_taxicab(5000)

if cube_results:
    print("Found:")
    for s, cube_root, pairs in cube_results[:10]:
        print(f"{s} = {cube_root}^3 = ", end="")
        representations = []
        for a, b in pairs:
            representations.append(f"{a}^3 + {b}^3")
        print(" = ".join(representations))
else:
    print("None found up to 5000")
EOF
